package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.apache.commons.math.util.MathUtils.normalizeAngle;
import static org.junit.Assert.*;

public class MathUtils_normalizeAngle_TriageGen0Test {

    private static final double TWO_PI = 2.0 * Math.PI;
    private static final double EPSILON = 1e-10;











    @Test
    public void testNormalizeAngle_DifferentCenter() {
        // Test with a center that is not zero
        double center = Math.PI;
        // a = 3PI is equivalent to PI (the center) in a 2PI cycle
        double a = 3.0 * Math.PI;
        double result = normalizeAngle(a, center);
        Assert.assertEquals(center, result, EPSILON);

        // a = 4PI. (4PI + PI - PI)/2PI = 2. floor(2) = 2. 4PI - 2PI*2 = 0.
        // Wait, let's check math: a - 2PI * floor((a + PI - center)/2PI)
        // a=4PI, center=PI: 4PI - 2PI * floor((4PI + PI - PI)/2PI) = 4PI - 2PI * floor(2) = 0
        double a2 = 4.0 * Math.PI;
        double result2 = normalizeAngle(a2, center);
        Assert.assertEquals(0.0, result2, EPSILON);
    }


}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.apache.commons.math.util.MathUtils.normalizeAngle;
import static org.junit.Assert.*;

public class MathUtils_normalizeAngle_TriageGen0Test {

    private static final double TWO_PI = 2.0 * Math.PI;
    private static final double EPSILON = 1e-10;













    @Test
    public void testNormalizeAngle_BoundaryConditions() {
        double center = 0.0;
        // Testing edge case near PI and -PI
        double aPos = Math.PI;
        // a + PI - 0 / 2PI = 1. floor(1) = 1. PI - 2PI = -PI
        // Note: Depending on floating point precision, PI might result in -PI or PI.
        // The formula: a - 2PI * floor((a + PI - center)/2PI)
        double resultPos = normalizeAngle(aPos, center);
        Assert.assertTrue(Math.abs(resultPos - (-Math.PI)) < EPSILON || Math.abs(resultPos - Math.PI) < EPSILON);

        double aNeg = -Math.PI;
        // -PI + PI - 0 / 2PI = 0. floor(0) = 0. -PI - 0 = -PI
        double resultNeg = normalizeAngle(aNeg, center);
        Assert.assertEquals(-Math.PI, resultNeg, EPSILON);
    }
}
